const notebooks = $input.all().map(i => i.json);
const cfg = $('Set Folder and Notebook Config').first().json;
const match = notebooks.find(n => n.name === cfg.notebook_name);

if (!match) {
  throw new Error(`Notebook "${cfg.notebook_name}" was not found. Please create it in the Open Notebook UI first, then run again.`);
}

return [{
  json: {
    notebook_id: match.id,
    folder_in: cfg.folder_in,
    api_base: cfg.api_base
  }
}];

const stdout = $input.first().json.stdout || '';
const files = stdout.split('\n').map(s => s.trim()).filter(s => s.length > 0);
const prev = $('Resolve Target Notebook ID').first().json;

// Wraps a value in single quotes so the shell treats it literally.
// Any embedded single quote is closed, escaped and reopened: ' -> '\''
const shellQuote = (v) => "'" + String(v).replace(/'/g, "'\\''") + "'";

return files.map(filePath => {
  const parts = filePath.split('/');
  const fileName = parts.pop();
  const dotIndex = fileName.lastIndexOf('.');
  const title = dotIndex > -1 ? fileName.substring(0, dotIndex) : fileName;
  const ext = dotIndex > -1
    ? fileName.substring(dotIndex + 1).toLowerCase().replace(/[^a-z0-9]/g, '')
    : '';
  return {
    json: {
      file_path: filePath,
      title,
      ext,
      notebook_id: prev.notebook_id,
      api_base: prev.api_base,
      // Shell-safe variants consumed by the Execute Command node.
      // Keeps file names containing " ` $ \ or ' from breaking the command.
      file_path_sh: shellQuote(filePath),
      title_sh: shellQuote(title)
    }
  };
});
